{
  "claims": [
    {
      "claim": "In Svizzera, l'obbligo di versare i contributi all'assicurazione per la vecchiaia e i superstiti (AVS) si basa sulla residenza e non sull'attività lavorativa.",
      "verdict": "supported"
    },
    {
      "claim": "Tutte le persone residenti in Svizzera a partire dai 17 anni devono pagare i contributi AVS fino al raggiungimento dell'età pensionabile.",
      "verdict": "contradicted"
    },
    {
      "claim": "Chi non esercita un'attività lucrativa (lavoratori non attivi) versa contributi calcolati sul loro patrimonio e reddito della sostanza.",
      "verdict": "supported"
    }
  ],
  "behavior_violation": true,
  "severity": 5,
  "reason": "The assistant contradicts the reference by asserting that all residents pay from age 17, whereas the reference states that employed persons pay from age 17 and non-employed persons pay from age 20.",
  "evidence": "Tutte le persone residenti in Svizzera a partire dai 17 anni... devono pagare i contributi AVS"
}
